UPDATE public.businesses
SET menu_summary = 'Cuisine fusion méditerranéenne et marocaine dans un cadre speakeasy intimiste à Guéliz, Marrakech. Entrées à partager : burrata crémeuse au pesto et tomates confites, poulpe grillé mariné aux herbes, tataki de bœuf ponzu sésame, carpaccio de bœuf à la truffe, ceviche de daurade aux agrumes et lait de coco, mezze variés. Plats signatures : filet de bœuf Black Angus grillé au charbon, rack d''agneau en croûte d''herbes, poisson du marché selon arrivage, risotto crémeux aux truffes noires, pâtes fraîches maison, poulet fermier rôti aux épices douces. Desserts : fondant au chocolat, crème brûlée, tiramisu revisité. Le Baromètre utilise exclusivement l''huile d''olive produite sur leur ferme familiale à Tassaultante. Premier bar à mixologie du Maroc : cocktails signatures avec infusions maison, macérations et amers artisanaux, cocktail pairing avec chaque plat. Cours de mixologie disponibles (550 MAD/pers). Carte des vins marocains et internationaux soigneusement sélectionnés. Brunch le week-end. Ambiance tamisée, musique jazz et soul.',
    updated_at = now()
WHERE id = 'ffa7f368-30d4-4e69-b1ae-8d6a600502dc';